// --- The ledger font (rom/font.bin, from book.py): 5 x 7 letters, 9 rows with the descenders ---
let GW = null, GP = null; // each glyph's width, and its lit pixels as [dx, dy, dx, dy ...]
function loadFont() {
  const b = rom('font'), n = b.length / 10;
  GW = new Uint8Array(n); GP = [];
  for (let g = 0; g < n; g++) {
    GW[g] = b[g * 10];
    const px = [];
    for (let y = 0; y < 9; y++) for (let x = 0; x < 5; x++) if ((b[g * 10 + 1 + y] >> x) & 1) px.push(x, y);
    GP.push(px);
  }
}
const gi = (ch) => { const g = ch.charCodeAt(0) - 32; return g >= 0 && g < GW.length ? g : 31; };
/** The width of a string in the ledger font, in pixels. */
function tw(s) { let w = 0; for (const ch of s) w += GW[gi(ch)] + 1; return w ? w - 1 : 0; }
/** Draw a string in the ledger font; returns the x after it. */
function tx(s, x, y, c) {
  for (const ch of s) {
    const g = gi(ch), px = GP[g];
    for (let k = 0; k < px.length; k += 2) pset(x + px[k], y + px[k + 1], c);
    x += GW[g] + 1;
  }
  return x;
}
const txr = (s, x, y, c) => tx(s, x - tw(s), y, c);
const txc = (s, y, c) => tx(s, 128 - (tw(s) >> 1), y, c);
/** Break text into lines that fit in w pixels. */
function wrap(s, w) {
  const out = []; let line = '';
  for (const word of s.split(' ')) {
    const next = line ? line + ' ' + word : word;
    if (tw(next) > w && line) { out.push(line); line = word; } else line = next;
  }
  if (line) out.push(line);
  return out;
}
/** System-font text with a shadow. */
function sys(s, x, y, c) { print(s, x + 1, y + 1, EDGE); print(s, x, y, c); }
const sysc = (s, y, c) => sys(s, 128 - s.length * 4, y, c);

// --- Numbers (spec 5: by name to decillion, then 1.2E36) ---
const BIG = ['thousand', 'million', 'billion', 'trillion', 'quadrillion', 'quintillion', 'sextillion', 'septillion',
  'octillion', 'nonillion', 'decillion'];
function commas(n) { return Math.floor(n).toString().replace(/\B(?=(\d{3})+(?!\d))/g, ','); }
function fmt(n) {
  if (!(n >= 1e6)) return commas(Math.max(0, n));
  const e = Math.floor(Math.log10(n) / 3);
  if (e <= BIG.length) return (n / 10 ** (3 * e)).toFixed(2) + ' ' + BIG[e - 1];
  return n.toExponential(1).toUpperCase().replace('+', '');
}
const SHORT = ['K', 'M', 'B', 'T', 'Qa', 'Qi', 'Sx', 'Sp', 'Oc', 'No', 'Dc'];
/** Short numbers for the panels' counters: 999,999 then 1.24M, 3.50B ... */
function fmts(n) {
  if (!(n >= 1e6)) return commas(Math.max(0, n));
  const e = Math.floor(Math.log10(n) / 3);
  if (e <= SHORT.length) return (n / 10 ** (3 * e)).toFixed(2) + SHORT[e - 1];
  return n.toExponential(1).toUpperCase().replace('+', '');
}
/** Costs, short: 9,500, then 150K, 2.5M, 100Qa (three figures at most). */
function fmtc(n) {
  if (n < 1e4) return commas(n);
  const e = Math.floor(Math.log10(n) / 3), v = n / 10 ** (3 * e);
  return e <= SHORT.length ? +v.toPrecision(3) + SHORT[e - 1] : n.toExponential(1).toUpperCase().replace('+', '');
}
const money = (n) => (n < 1000 ? 'L ' + n.toFixed(2) : 'L ' + fmts(n)); // lire
const rate = (n) => (n < 10 ? n.toFixed(1) : fmts(n));

