/** The run's own random numbers (mulberry32), so a saved run carries on the same way. */
function rand() {
  let t = (G.rng = (G.rng + 0x6d2b79f5) >>> 0);
  t = Math.imul(t ^ (t >>> 15), t | 1); t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
  return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
}
const gauss = () => Math.sqrt(-2 * Math.log(1 - rand())) * Math.cos(2 * Math.PI * rand());

const market = () => (T.mktLow + (T.mktHigh - T.mktLow) * (0.5 - 0.5 * Math.cos((2 * Math.PI * G.day) / T.dayLen))) * G.brassX;
/** Cogs the town buys a second, at the current price and sign. */
const salesRate = () => T.sales0 * T.signMul ** (G.sign - 1) * G.mSales * (T.price0 / G.price) ** T.priceExp;
const tinkerCost = () => T.tinkerCost * T.tinkerMul ** G.tinkers;
const benchCost = () => T.benchCost * T.benchMul ** G.benches;
const signCost = () => (T.signCost * 2 ** (G.sign - 1)) / G.signDiv;
const tinkerRate = () => G.tinkers * T.tinkerRate * G.mTink * G.mAll;
const benchRate = () => (G.benchOn ? G.benches * T.benchRate * G.mBench * G.mAll : 0);
const makeRate = () => tinkerRate() + benchRate();
const insRate = () => (G.mind ? (G.escapements * T.insPerEsc + (G.act === 2 ? dreamShare() * swarmLog() * T.dreamIns : 0) + (G.mothIns ? Math.log10(Math.max(1, G.moths)) * T.mothIns : 0)) * G.mIns : 0);
const insCap = () => G.barrels * T.insPerBarrel * G.mBarrel;
const freeTrust = () => G.trust - (G.escapements - 1) - (G.barrels - 1);
const fib = (k) => { let a = 1, b = 2; for (let i = 0; i < k; i++) [a, b] = [b, a + b]; return b; };
/** The cogs made at which the next trust comes: 2,000, 3,000, 5,000, 8,000 ... (the Fibonacci numbers x 1,000). */
const nextTrust = () => fib(G.trust - 2 - trustGiven()) * 1000;
let trustGiven = () => 0; // trust that came from inventions, not from cogs made (set once the book is read)
const riddleCost = () => T.riddle0 * T.riddleMul ** G.solved;

/** Make up to n cogs from the brass there is; returns how many. */
function make(n) {
  n = Math.min(n, Math.floor(G.brass * G.mOz + 1e-9));
  if (n <= 0) { raise('nobrass'); return 0; }
  G.brass = Math.max(0, G.brass - n / G.mOz); G.cogs += n; G.made += n;
  return n;
}

/** One tick of the world: dt seconds. */
function step(dt) {
  if (G.act === 2) return step2(dt);
  if (G.act === 3) return step3(dt);
  if (G.act !== 1) return;
  G.time += dt; G.day += dt;
  G.spool += (market() - G.spool) * (1 - (1 - T.spoolFall) ** dt);
  if (G.contract && G.contractUse) for (let k = 0; k < 5 && G.brass * G.mOz < makeRate() * T.contractLow && G.coin >= G.spool; k++) ACT.brass();
  G.mk += makeRate() * dt;
  if (G.mk >= 1) { const n = Math.floor(G.mk); G.mk -= n; make(n); }
  const s = Math.min(G.cogs, salesRate() * dt);
  G.cogs -= s; G.sold += s; G.coin += (s * G.price * G.mRev) / (G.boxOnly && !isDone(10) ? 2 * G.boxOnly : 1);
  if (G.cogs >= T.unsold) raise('unsold');
  // the mind: insight up to what the barrels hold; trust from cogs made
  if (!G.mind && G.made >= T.mindAt) { G.mind = 1; raise('mind'); }
  G.insight = Math.min(insCap(), G.insight + insRate() * dt);
  while (G.made >= nextTrust()) G.trust++;
  if (G.engine) G.clev += T.engineRate * dt;
  if (G.bank > 0) {
    const k = RISKS[G.risk], r = (k.mu * dt) / 60 + k.s * Math.sqrt(dt / 60) * gauss();
    G.bank *= 1 + r;
    if (k.crash && rand() < (k.crash * dt) / 60) { G.bank *= 1 - k.loss; raise('bankdown'); }
    if (r < -0.01) raise('bankdown');
  }
  if (G.ordersOn) {
    if (G.oNeed) { G.oLeft -= dt; if (G.oLeft <= 0) G.oNeed = 0; }
    else if ((G.oNext -= dt) <= 0) newOrder();
  }
  checkInventions(); checkStory(); checkMiles();
}

function newOrder() {
  const r = Math.max(1, makeRate() + salesRate() / 2);
  G.oNeed = Math.max(50, Math.round(r * (20 + rand() * 40)));
  G.oPay = G.oNeed * G.price * G.mRev * T.orderPay;
  G.oLeft = T.orderLife; G.oNext = T.orderEvery; G.oFor = Math.floor(rand() * ORDER_FOR.length);
  raise('order');
}

// --- The gear riddles: two stages (a driver turning a driven gear, twice, on a shared axle) and an idler ---
// The output turns (A / B) x (C / D) times for each turn of the input; two meshes turn it the same way, the idler
// reverses it. A riddle's target and the player's picks are packed into numbers (rTarget, rPicks) for the save.
const gcd = (a, b) => (b ? gcd(b, a % b) : a);
function ratio(a, b, c, d) { const n = a * c, m = b * d, g = gcd(n, m); return [n / g, m / g]; }
const unpackPicks = (v) => [v & 7, (v >> 3) & 7, (v >> 6) & 7, (v >> 9) & 7, (v >> 12) & 1];
const packPicks = (p) => p[0] | (p[1] << 3) | (p[2] << 6) | (p[3] << 9) | (p[4] << 12);
function riddleTarget() { const v = G.rTarget; return [v & 255, (v >> 8) & 255, (v >> 16) & 1]; }
function picked() { const p = unpackPicks(G.rPicks); return [...ratio(GEARS[p[0]], GEARS[p[1]], GEARS[p[2]], GEARS[p[3]]), p[4]]; }
const ratioText = (n, m, rev) => `${n}:${m} ${rev ? 'reversed' : 'same way'}`;


/** An invention's effects on the run's numbers; replay: only the multipliers and flags (when a save is loaded). */
function applyEffects(v, replay) {
  for (const e of v.effect) {
    if (replay && !derived(e.k)) continue;
    if (e.op === '*') G[e.k] *= e.v; else if (e.op === '+') G[e.k] += e.v; else G[e.k] = e.v;
  }
}
const actOf = (id) => (id <= 40 ? 1 : id <= 80 ? 2 : 3);

// --- Act II: the Winding of the World. Ore is dug, smelted to brass and cut into cogs; every machine draws spring
// power, which waterwheels wind (more or less as the river rises and falls) and spring barrels store ---
const workShare = () => (G.dreamOn ? (10 - G.dream) / 10 : 1);
const dreamShare = () => (G.dreamOn ? G.dream / 10 : 0);
const swarmLog = () => Math.log10(Math.max(10, G.swarm));
const sulking = () => !G.noSulk && G.sulkT >= T.sulkAfter;
const machines = () => G.diggers + G.foundries + G.mills;
const powerCap = () => T.power0 + G.sbarrels * T.sbCap * G.mSB;
const powerNeed = () => machines() * T.draw * G.mDraw;
const river = () => 1 + T.river * Math.sin((2 * Math.PI * G.time) / T.riverDay);
const powerGen = () => G.wheels * T.wheelGen * G.mWheel * river();
const workBoost = () => 1 + workShare() * (sulking() && G.dream === 0 ? 0.5 : 1);
const machRate = (n, m) => n * T.machRate * m * G.mMach * workBoost();
const ingRate = () => dreamShare() * swarmLog() * T.dreamIng * (sulking() && G.dream === 10 ? 0.5 : 1);
const COSTS2 = { diggers: 'digCost', foundries: 'foundCost', mills: 'millCost', wheels: 'wheelCost', sbarrels: 'sbCost' };
const cost2 = (k) => T[COSTS2[k]];
const worldOre = () => T.regionOre.reduce((a, b) => a + b, 0);
let eff2 = 1; // the share of the machines' work the spring power could drive, last tick

function step2(dt) {
  G.time += dt;
  // spring power: wound by the wheels, stored up to the barrels' total, drawn by every machine
  const have = G.power + powerGen() * dt, need = powerNeed() * dt;
  eff2 = need > 0 ? Math.min(1, have / need) : 1;
  G.power = Math.min(powerCap(), Math.max(0, have - need * eff2));
  if (need > 0 && eff2 < 0.05) raise('nopower');
  // the chain: dig, smelt, cut
  const dug = Math.min(G.ore, machRate(G.diggers, G.mDig) * eff2 * dt);
  G.ore -= dug; G.yard += dug; G.dugT += dug; G.wound = Math.min(1, G.wound + dug / worldOre());
  if (G.ore <= 0 && G.region && G.regDone < G.region) { G.ore = 0; G.regDone = G.region; raise('regdone'); }
  if (G.regDone === 4) G.wound = 1; // every place dug: the world is all cogs
  const smelt = Math.min(G.yard, machRate(G.foundries, G.mFound) * eff2 * dt);
  G.yard -= smelt; G.brass += smelt;
  const cut = Math.min(G.brass, machRate(G.mills, G.mMill) * eff2 * dt);
  G.brass -= cut; G.cogs += cut * G.mOz; G.made += cut * G.mOz;
  // the old shop's tinkers and workbenches go on making cogs from Rotella's old clocks, so the chain can always begin again
  const old = makeRate() * dt; G.cogs += old; G.made += old;
  if (G.yard > 1e6 && G.yard > machRate(G.diggers, G.mDig) * 60) raise('yardfull');
  if (G.brass > 1e6 && G.brass > machRate(G.foundries, G.mFound) * 60) raise('brassfull');
  // the swarm grows by itself; at one end of the slider for too long, it sulks
  G.swarm *= 1 + (T.swarmGrow * dt) / 60;
  if (G.dreamOn && (G.dream === 0 || G.dream === 10)) { G.sulkT += dt; if (sulking()) raise('sulk'); } else G.sulkT = 0;
  const ing = ingRate() * dt; G.ingen += ing; G.ingT += ing;
  G.insight = Math.min(insCap(), G.insight + insRate() * dt);
  // trust: one for each power of ten of cogs made from 100 million, and at 10, 100, 1,000 ... ingenuity
  const want = Math.max(0, Math.floor(Math.log10(Math.max(1, G.made))) - 7) + (G.ingT >= 10 ? Math.floor(Math.log10(G.ingT)) : 0);
  while (G.trust2 < want) { G.trust2++; G.trust++; }
  if (G.autoOn && G.auto) autoBuild(dt);
  checkInventions(); checkStory(); checkMiles();
}

/** How many of a machine a press builds now (the lot, or as many as the cogs allow). */
const lotOf = (k) => { const n = LOTS[G.lot]; return n || Math.max(1, Math.floor(G.cogs / cost2(k))); };
function build(k, n) {
  const c = cost2(k), can = Math.min(n, Math.floor(G.cogs / c));
  if (can < 1) return 0;
  G[k] += can; G.cogs -= can * c;
  return can;
}
/** The Tinker Works: a share of the cogs each second goes to the machine the chain needs most. */
function autoBuild(dt) {
  let spend = G.cogs * (G.auto / 10) * Math.min(1, dt * 2);
  for (let k = 0; k < 4 && spend > 0; k++) {
    const need = powerGen() < powerNeed() * 1.2 ? 'wheels' : powerCap() < powerNeed() * 20 ? 'sbarrels' : G.yard > machRate(G.foundries, G.mFound) * 10 ? 'foundries'
      : G.brass > machRate(G.mills, G.mMill) * 10 ? 'mills' : G.ore > 0 ? 'diggers' : 'mills';
    const n = Math.floor(spend / 4 / cost2(need));
    if (n < 1) break;
    spend -= build(need, n) * cost2(need);
  }
}

/** The start of an act's play, after the act before it ends (its cinematic comes in step 7). */
function endAct(from) {
  checkMiles(); saveRun(); fx(SFX.act);
  if (from < 3) playScene(from === 1 ? 'town' : 'launch', () => {});
  if (from === 1) {
    raise('act2'); tab = 0; row = 0; top = 0;
    G.swarm = Math.max(1000, G.tinkers * 1000 + G.benches * 10000);
    G.brass = 0; G.cogs = Math.max(G.cogs, 0);
  } else if (from === 2) {
    raise('act3'); tab = 0; row = 0; top = 0;
    G.moths = G.mothsMax = T.moths0; G.yard = 0; G.brass = 0;
  } else { state = 'choice'; choiceSel = 0; timer = 0; raise('choice'); }
  saveRun();
}


// --- Act III: the Orrery. Moths reach stars, wind them, and copy themselves from the cogs the wound stars give;
// some are lost in the dark, and from the first million wound stars the Rust fights them ---
const TRAITS = ['SPEED', 'WINDING', 'COPYING', 'HARVEST', 'WINGS', 'SHELTER'];
const TRAIT_HINT = ['Reach new stars faster.', 'Wind the stars reached faster.', 'Moths build more moths, from cogs.',
  'More cogs from each wound star.', 'Fight the Rust: each point is a sharper sting.', 'Fewer moths lost in the dark.'];
const tf = (i) => 1 + G['tr' + i]; // a trait's factor: one more for each blueprint in it
/** Six, one for each power of ten of the most moths there have been (so they never shrink), and inventions'. */
const blueprints = () => T.bp0 + Math.floor(Math.log10(Math.max(1, G.mothsMax))) + G.bpBonus + G.bpDrawn;
const drawCost = () => T.draw0 * 2 ** G.bpDrawn;
const freeBp = () => blueprints() - TRAITS.reduce((s, _, i) => s + G['tr' + i], 0);
const mothCost = () => T.mothCost * G.mCostM;
const reachRate = () => G.moths * T.reachRate * tf(0) * G.mSpeed;
const windRate = () => G.moths * T.windRate * tf(1) * G.mWind;
/** Moths built a second: as many as the moths can build, and as the nests on the wound stars can hold. */
const copyRate = () => Math.min(G.moths * T.copyRate, T.nest0 + G.starsW * T.nest) * tf(2) * G.mCopy;
const harvRate = () => G.starsW * T.harvRate * tf(3) * G.mHarv;
const lossRate = () => (G.moths * T.lossRate * G.mLoss) / (tf(5) * G.mShelter);
/** The Rust stung away a second: a share of it for each blueprint in WINGS (none in WINGS, no sting). */
const stingRate = () => G.rust * T.sting * G.tr4 * G.mWings;
const rustRate = () => G.rust * T.rustKill * G.rustX;

function step3(dt) {
  G.time += dt;
  G.reached = Math.min(T.stars, G.reached + reachRate() * dt);
  G.starsW = Math.min(G.reached, G.starsW + windRate() * dt);
  if (G.starsW >= T.stars * 0.999999) G.starsW = T.stars;
  G.starsP = G.starsW / T.stars;
  const h = harvRate() * dt; G.cogs += h; G.made += h;
  const want = copyRate() * dt, n = Math.min(want, G.cogs / mothCost());
  G.moths += n; G.cogs -= n * mothCost();
  if (want > 1 && n < want / 2) raise('nocogs');
  const lost = Math.min(G.moths, lossRate() * dt); G.moths -= lost; G.lostT += lost;
  if (!G.rustSeen && G.starsW >= G.rustAt) { G.rustSeen = 1; G.rust = G.moths * 0.01; raise('rust'); fx(SFX.rust); }
  if (G.rust > 0) {
    const took = Math.min(G.moths, rustRate() * dt), stung = Math.min(G.rust, stingRate() * dt);
    G.moths -= took; G.rustT += took;
    // the Rust grows only from the moths it takes and loses, and is never more than twice the moths: a blueprint in
    // WINGS always turns it back
    G.rust = Math.min(2 * G.moths, G.rust + lost * T.rustFrom + took * T.rustKeep - stung);
    if (took > n + stung) raise('rustwins');
    if (G.luciaOn) { const back = G.rust * T.lucia * dt; G.rust -= back; G.moths += back; raise('luciahome'); }
    G.rust = Math.max(0, G.rust);
  }
  G.moths = Math.max(T.mothsMin, G.moths); // Marco always has a few moths left to begin again
  G.mothsMax = Math.max(G.mothsMax, G.moths);
  G.insight = Math.min(insCap(), G.insight + insRate() * dt);
  const want3 = Math.max(0, Math.floor(Math.log10(Math.max(1, G.starsW))));
  while (G.trust3 < want3) { G.trust3++; G.trust++; }
  checkInventions(); checkStory(); checkMiles();
}

// --- The cinematics (scenes.txt, in the ROM): shots of a view with effects and a caption ---
let cine = null; // { shots, k (the shot), t (its frame), then (what follows) }
function playScene(name, then) {
  if (skipTitle || !SCENES[name]) return then();
  cine = { shots: SCENES[name], k: 0, t: 0, then }; state = 'cine'; typed = 0;
}
const shot = () => cine.shots[cine.k];
const fxOn = (e) => cine && state === 'cine' && shot().fx.includes(' ' + e + ' ');
/** A shot plays and types its caption, then waits (HOLD frames before its end) for A, so there is time to read it;
 * after A it plays its last part (a fade, a dissolve) and the next shot begins. A while the caption types shows it
 * whole; A once it is read moves on at once; START skips the scene. */
const HOLD = 30;
const waiting = () => cine.t >= shot().f - HOLD && !cine.go;
function updateCine() {
  const s = shot();
  if (!waiting()) cine.t++;
  typed += 2;
  if (fxOn('tick') && clock % 40 === 1) fx(SFX.tick);
  if (pressed(A)) {
    if (typed < s.cap.length) typed = s.cap.length;
    else { cine.go = true; cine.t = Math.max(cine.t, s.f - HOLD); fx(SFX.move); }
  }
  const next = pressed(START) ? cine.shots.length : cine.t >= s.f ? cine.k + 1 : cine.k;
  if (next !== cine.k) {
    cine.k = next; cine.t = 0; typed = 0; cine.go = false;
    if (next >= cine.shots.length) { brightness(15); mosaic(1); winmask('screen', null); VY = 0; const f = cine.then; cine = null; state = 'play'; timer = 0; f(); }
  }
}
function drawCine() {
  const s = shot(), p = cine.t / s.f, e = 30 / s.f;
  brightness(flr(15 * Math.min(1, fxOn('fadein') ? p / e : 1, fxOn('fadeout') ? (1 - p) / e : 1)));
  mosaic(fxOn('mosaicout') ? 1 + flr(Math.max(0, p - 0.5) * 30) : fxOn('mosaicin') ? 1 + flr(Math.max(0, 0.5 - p) * 30) : 1);
  irisR = fxOn('irisclose') ? lerp(150, 26, Math.min(1, p * 1.5)) : fxOn('irisopen') ? lerp(26, 220, p) : 0;
  winmask('screen', irisR ? { w1: 'out' } : null);
  drawView();
  if (fxOn('launch')) for (let i = 0; i < 24; i++) { const a = i * 2.4, r = 30 + ((clock * (1 + (i % 4))) % 120); sprite((clock + i) % 12 < 6 ? S.moth0 : S.moth1, 124 + Math.cos(a) * r, GLOBE_Y - 4 + Math.sin(a) * r * 0.6); }
  wrap(s.cap.slice(0, typed), 224).forEach((l, i) => txc(l, VY + 104 + i * 11, s.cap.startsWith('ACT ') ? GOLD : INK));
  if (waiting() && typed >= s.cap.length && clock % 50 < 34) txr(`A: on ${RM}`, 248, 210, DIM); // waiting to be read
}
let irisR = 0;

// --- The end: the watch, and the choice ---
const CHOICES = ['WIND IT', 'LET IT STOP'];
let choiceSel = 0;
function choose(k) {
  G.ending = k + 1; if (k === 0) G.endD = 1; else G.endR = 1;
  dset(ENDS_SLOT, dget(ENDS_SLOT) | (1 << k)); // the endings seen, over every cycle
  checkMiles(); raise(k === 0 ? 'dominion' : 'rest');
  dset(CYCLE_SLOT, Math.max(dget(CYCLE_SLOT), G.cycle + 1)); putD(ALL_SLOT, getD(ALL_SLOT) + G.made);
  G.act = 5; saveRun(); dset(RUN_SLOT, 0); endSel = 0; // the story is told: nothing to continue
  const end = () => { state = 'ending'; timer = skipTitle ? 0 : CREDITS_AT; };
  if (skipTitle) end(); else playScene(k === 0 ? 'dominion' : 'stop', end);
}

// --- What the player can do (the panel's rows and the hand call these; the bot and the tests too) ---
let why = '', quiet = false; // why the last action could not be done, for the hint line; quiet: it made its own sound
const sound = (n) => { fx(n); quiet = true; };
const no = (s) => { why = s; return false; };
const ACT = {
  hand() {
    if (G.act === 3) {
      const n = Math.min(G.mHand, Math.floor(G.cogs / mothCost()));
      if (n < 1) return no(`A moth costs ${fmtc(mothCost())} cogs.`);
      G.moths += n; G.cogs -= n * mothCost(); return true;
    }
    if (G.act === 2) { if (G.power >= powerCap()) return no('The springs are wound as far as they go.'); G.power = Math.min(powerCap(), G.power + T.handPower * G.mHand); return true; }
    // stranded (no brass, no cogs to sell, not the lire for a spool): the shavings swept off the bench make a cog
    if (G.brass * G.mOz < 1 && G.cogs < 1 && G.coin < G.spool) { G.brass += 1 / G.mOz; raise('shavings'); }
    return make(G.hand) ? true : no('No brass left. Buy a spool from Signore Ferrese.');
  },
  build(k) { return build(k, lotOf(k)) ? true : no(`Not enough cogs: ${fmts(cost2(k))} each.`); },
  lot(d) { const l = G.lot + d; if (l < 0 || l >= LOTS.length) return no('There is no other size of lot.'); G.lot = l; return true; },
  dream(d) { const v = G.dream + d; if (v < 0 || v > 10) return no('The slider is at its end.'); G.dream = v; return true; },
  drawBp() { const c = drawCost(); if (G.insight < c) return no(`A blueprint costs ${fmtc(c)} insight.`); G.insight -= c; G.bpDrawn++; return true; },
  trait(i, d) {
    const v = G['tr' + i] + d;
    if (v < 0) return no('No blueprints in it to take back.');
    if (d > 0 && freeBp() < 1) return no('No blueprints left. More come with every power of ten of moths.');
    G['tr' + i] = v; return true;
  },
  auto(d) { const v = G.auto + d; if (v < 0 || v > 10) return no('That is as far as it goes.'); G.auto = v; return true; },
  price(d) {
    const p = Math.round((G.price + d * T.priceStep) * 100) / 100;
    if (p < T.priceMin || p > T.priceMax) return no('That is as far as the price goes.');
    G.price = p; G.priceMoves++; raise(d > 0 ? 'priceup' : 'pricedown');
    return true;
  },
  brass() {
    if (G.coin < G.spool) return no('Not enough lire for a spool.');
    G.coin -= G.spool; G.brass += G.spoolOz; G.spool += T.spoolRise; G.spools++;
    return true;
  },
  sign() {
    if (G.sign >= T.signMax) return no('The sign is as grand as it can be.');
    const c = signCost(); if (G.coin < c) return no('Not enough lire to repaint the sign.');
    G.coin -= c; G.sign++;
    return true;
  },
  tinker() {
    const c = tinkerCost(); if (G.coin < c) return no('Not enough lire for the parts.');
    G.coin -= c; G.tinkers++;
    return true;
  },
  bench() {
    const c = benchCost(); if (G.coin < c) return no('Not enough lire for a workbench.');
    G.coin -= c; G.benches++;
    return true;
  },
  escapement() { if (freeTrust() < 1) return no(`No trust to spend. More comes at ${fmt(nextTrust())} cogs made.`); G.escapements++; return true; },
  barrel() { if (freeTrust() < 1) return no(`No trust to spend. More comes at ${fmt(nextTrust())} cogs made.`); G.barrels++; return true; },
  contract() { G.contractUse ^= 1; return true; },
  fill() {
    if (!G.oNeed) return no('There is no order waiting.');
    if (G.cogs < G.oNeed) return no(`Not enough cogs in stock: ${fmt(G.oNeed)} are needed.`);
    G.cogs -= G.oNeed; G.coin += G.oPay; G.oNeed = 0; G.orders++;
    return true;
  },
  invent(id) {
    const v = INV_BY[id];
    if (!v || isDone(id)) return no('Already made.');
    if (!canAfford(v.cost)) return no(`Not yet: it needs ${costText(v.cost)}.`);
    pay(v.cost); G.done[id >> 5] |= 1 << (id & 31); G.invs++;
    const act = G.act, region = G.region;
    applyEffects(v, false); sound(SFX.invent);
    addLog(v.story, true);
    if (G.watch) raise('watch');
    if (v.id === 27) playScene('rest', () => {});
    if (v.id === 99) playScene('orrery', () => {});
    if (G.region !== region) { G.ore += T.regionOre[G.region]; sound(SFX.place); } // a new place: its ore, on top of what is left
    if (G.act !== act) endAct(act);
    return true;
  },
  pose() {
    if (G.rTarget) return no('A riddle is already on the bench.');
    const c = riddleCost(); if (G.insight < c) return no(`A riddle costs ${fmt(c)} insight.`);
    G.insight -= c;
    const two = G.solved >= 5, pick = () => Math.floor(rand() * GEARS.length);
    let t;
    do {
      const a = pick(), b = pick(), c2 = two ? pick() : 0, d = two ? pick() : 0;
      t = [...ratio(GEARS[a], GEARS[b], GEARS[c2], GEARS[d]), rand() < 0.5 ? 1 : 0];
    } while (t[0] === t[1] || t[0] > 255 || t[1] > 255);
    G.rTarget = t[0] | (t[1] << 8) | (t[2] << 16) | (1 << 20);
    G.rPicks = 0; G.rReward = Math.round((two ? 10 : 5) * (1 + G.solved / 10)); G.rCost = c;
    return true;
  },
  gear(slot, d) {
    const p = unpackPicks(G.rPicks);
    p[slot] = slot === 4 ? p[4] ^ 1 : (p[slot] + d + GEARS.length) % GEARS.length;
    G.rPicks = packPicks(p); return true;
  },
  tryIt() {
    if (!G.rTarget) return no('Pose a riddle first.');
    const [n, m, rev] = riddleTarget(), [a, b, r] = picked();
    if (n !== a || m !== b || rev !== r) { sound(SFX.wrong); return no(`Not yet: that turns ${ratioText(a, b, r)}.`); }
    G.clev += G.rReward; G.solved++; G.rTarget = 0; sound(SFX.solve);
    return true;
  },
  giveUp() { G.rTarget = 0; return true; },
  risk(d) { const r = G.risk + d; if (r < 0 || r > 2) return no('There is no other risk.'); G.risk = r; return true; },
  deposit(share) {
    const v = Math.floor(G.coin * share * 100) / 100; if (v <= 0) return no('No lire to put in.');
    G.coin -= v; G.bank += v * (1 - BANK.fee); G.bankIn += v; G.bankAt = G.time; raise('bank1');
    return true;
  },
  withdraw() {
    if (G.bank <= 0) return no('The ledger is empty.');
    const w = Math.ceil(G.bankAt + BANK.lock - G.time); if (w > 0) return no(`The lire stay in for ${w} s more.`);
    G.coin += G.bank; G.bank = 0; G.bankIn = 0; return true;
  },
};

// --- Triggers: `made:1000` (a number of the run has reached 1,000), `inv:7` (invention 7 is made), `ev:name` ---
function parseTrig(s) {
  return s.split('&').map((p) => {
    const c = p.indexOf(':'), k = p.slice(0, c), v = p.slice(c + 1);
    return k === 'ev' ? { ev: v } : k === 'inv' ? { inv: +v } : { k, n: +v };
  });
}
const holds = (ts) => ts.every((t) => (t.inv ? isDone(t.inv) : t.k ? G[t.k] >= t.n : false));

// --- The book (rom/book.bin, from book.py): the story, the inventions and the milestones ---
let STORY = [], INVS = [], INV_BY = [], MILES = [], SCENES = {};
function loadBook() {
  const b = rom('book'); let i = 3;
  const str = () => { const n = b[i++]; let s = ''; for (let k = 0; k < n; k++) s += String.fromCharCode(b[i++]); return s; };
  const count = () => { const n = b[i] | (b[i + 1] << 8); i += 2; return n; };
  STORY = []; INVS = []; INV_BY = []; MILES = [];
  for (let j = count(); j > 0; j--) { const trig = str(), text = str(); STORY.push({ t: parseTrig(trig), ev: trig.startsWith('ev:') ? trig.slice(3) : null, text }); }
  for (let j = count(); j > 0; j--) {
    const id = b[i++], name = str(), when = parseTrig(str()), cost = parseCost(str()), effect = str().split(' ').map((e) => {
      const m = e.match(/^(\w+)([*=+])([\d.]+)$/); return { k: m[1], op: m[2], v: +m[3] };
    }), hint = str(), story = str();
    const v = { id, name, when, cost, effect, hint, story };
    INVS.push(v); INV_BY[id] = v;
  }
  for (let j = count(); j > 0; j--) { const trig = str(), name = str(); MILES.push({ t: parseTrig(trig), name }); }
  for (let j = b[i++]; j > 0; j--) {
    const name = str(), shots = [];
    for (let k = b[i++]; k > 0; k--) { const view = str(), f = b[i] | (b[i + 1] << 8); i += 2; shots.push({ view, f, fx: ' ' + str() + ' ', cap: str() }); }
    SCENES[name] = shots;
  }
  // trust from inventions does not move the cogs needed for the next trust from cogs made
  trustGiven = () => INVS.reduce((s, v) => s + (isDone(v.id) ? v.effect.filter((e) => e.k === 'trust' && e.op === '+').reduce((a, e) => a + e.v, 0) : 0), 0);
}
function parseCost(s) { const c = {}; for (const p of s.split(' ')) { const [k, v] = p.split(':'); c[k] = +v; } return c; }
const COST_HAVE = { ins: () => G.insight, clev: () => G.clev, ing: () => G.ingen, lire: () => G.coin, cogs: () => G.cogs, trust: () => freeTrust() };
const COST_KEY = { ins: 'insight', clev: 'clev', ing: 'ingen', lire: 'coin', cogs: 'cogs', trust: 'trust' };
const canAfford = (c) => Object.keys(c).every((k) => COST_HAVE[k]() >= c[k]);
function pay(c) { for (const k in c) G[COST_KEY[k]] -= c[k]; }
function costText(c) {
  return Object.keys(c).map((k) => (k === 'lire' ? 'L ' + fmtc(c[k]) : `${fmtc(c[k])} ${k}`)).join(' + ');
}
const isDone = (id) => (G.done[id >> 5] >>> (id & 31)) & 1;
const isShown = (id) => (G.shown[id >> 5] >>> (id & 31)) & 1;
let newInv = false; // an invention has appeared since INVENT was last open
function checkInventions() {
  for (const v of INVS) if (!isShown(v.id) && holds(v.when)) { G.shown[v.id >> 5] |= 1 << (v.id & 31); newInv = true; }
}
const available = () => INVS.filter((v) => isShown(v.id) && !isDone(v.id) && actOf(v.id) === G.act);

// --- The story: each line told once a run, when its trigger first holds ---
const isTold = (j) => (G.told[j >> 5] >>> (j & 31)) & 1;
function tell(j) { G.told[j >> 5] |= 1 << (j & 31); addLog(STORY[j].text, true); }
function checkStory() { for (let j = 0; j < STORY.length; j++) if (!STORY[j].ev && !isTold(j) && holds(STORY[j].t)) tell(j); }
function raise(ev) { for (let j = 0; j < STORY.length; j++) if (STORY[j].ev === ev && !isTold(j)) tell(j); }

// --- Milestones: the play time each was first reached (saved as seconds + 1; 0 not yet) ---
function checkMiles() {
  MILES.forEach((m, j) => {
    if (G.mile[j] || !holds(m.t)) return;
    G.mile[j] = Math.floor(G.time) + 1; milestoneAt = clock; if (state === 'play') fx(SFX.mile);
    const b = BESTS.indexOf(m.name), old = b >= 0 ? dget(BEST_SLOT + b) : 0;
    if (b >= 0 && (!old || G.mile[j] < old)) dset(BEST_SLOT + b, G.mile[j]);
  });
}
let milestoneAt = -999;
/** The milestone reached last (the latest time). */
function lastMile() { let b = -1; for (let j = 0; j < MILES.length; j++) if (G.mile[j] && (b < 0 || G.mile[j] >= G.mile[b])) b = j; return b; }
const clockText = (s) => `${Math.floor(s / 3600)}:${String(Math.floor(s / 60) % 60).padStart(2, '0')}:${String(Math.floor(s) % 60).padStart(2, '0')}`;

// --- The log: the story's lines, wrapped; the newest types itself in ---
const LOG_W = 246;
let logRows = [], typed = 0, typing = 0, logScroll = 0;
function addLog(text, fresh) {
  const rows = wrap(text, LOG_W);
  rows.forEach((s, k) => logRows.push({ s, first: k === 0 }));
  if (logRows.length > 400) logRows.splice(0, logRows.length - 400);
  if (fresh) { typing = rows.length; typed = 0; if (state === 'play') fx(SFX.story); }
}
/** Rebuild the log from the lines told (after loading a run), in the story's order. */
function rebuildLog() {
  logRows = []; typing = 0;
  for (let j = 0; j < STORY.length; j++) if (isTold(j)) addLog(STORY[j].text, false);
  for (const v of INVS) if (isDone(v.id)) addLog(v.story, false);
}

// --- Save slots (spec section 13). Doubles take two slots: their 64 bits as two int32 ---
const VERSION_SLOT = 0, SAVE_VERSION = 3, CYCLE_SLOT = 1, RUN_SLOT = 2, TIME_SLOT = 3, SEED_SLOT = 5, SET_SLOT = 6;
const UI_SLOT = 7, KEYS_SLOT = 10, INTS_SLOT = 130, DONE_SLOT = 170, TOLD_SLOT = 174, SHOWN_SLOT = 190, MILE_SLOT = 198;
const f64 = new Float64Array(1), i32 = new Int32Array(f64.buffer);
function putD(slot, v) { f64[0] = v; dset(slot, i32[0]); dset(slot + 1, i32[1]); }
function getD(slot) { i32[0] = dget(slot); i32[1] = dget(slot + 1); return f64[0]; }
function saveRun() {
  dset(RUN_SLOT, 1 | (G.act << 8) | (G.cycle << 16)); putD(TIME_SLOT, G.time); dset(SEED_SLOT, G.seed);
  dset(UI_SLOT, tab | (row << 8));
  SAVE_KEYS.forEach((k, i) => putD(KEYS_SLOT + 2 * i, G[k]));
  SAVE_INTS.forEach((k, i) => dset(INTS_SLOT + i, G[k] | 0));
  for (let i = 0; i < 16; i++) dset(TOLD_SLOT + i, G.told[i] | 0);
  for (let i = 0; i < 4; i++) { dset(DONE_SLOT + i, G.done[i] | 0); dset(SHOWN_SLOT + i, G.shown[i] | 0); }
  for (let i = 0; i < 40; i++) dset(MILE_SLOT + i, G.mile[i]);
}
const hasRun = () => (dget(RUN_SLOT) & 255) === 1;
function loadRun() {
  G = freshRun(dget(SEED_SLOT), dget(RUN_SLOT) >> 16);
  G.act = (dget(RUN_SLOT) >> 8) & 255;
  SAVE_KEYS.forEach((k, i) => { G[k] = getD(KEYS_SLOT + 2 * i); });
  SAVE_INTS.forEach((k, i) => { G[k] = dget(INTS_SLOT + i); });
  G.rng >>>= 0;
  for (let i = 0; i < 16; i++) G.told[i] = dget(TOLD_SLOT + i) >>> 0;
  for (let i = 0; i < 4; i++) { G.done[i] = dget(DONE_SLOT + i) >>> 0; G.shown[i] = dget(SHOWN_SLOT + i) >>> 0; }
  for (let i = 0; i < 40; i++) G.mile[i] = dget(MILE_SLOT + i);
  for (const v of INVS) if (isDone(v.id)) applyEffects(v, true); // the multipliers and flags, again
  const ui = dget(UI_SLOT); tab = ui & 255; row = (ui >> 8) & 255;
  rebuildLog();
}
function saveSettings() { dset(SET_SLOT, (soundOn ? 1 : 0) | (musicOn ? 2 : 0) | 4); }
function loadSettings() { const s = dget(SET_SLOT); if (s & 4) { soundOn = s & 1; musicOn = (s >> 1) & 1; } }


