let tab = 0, row = 0, top = 0, hintMsg = '', hintT = 0, onTabs = false;
const openTabs = () => TABS.filter((t) => (!t.acts || t.acts === G.act) && (!t.when || t.when()));
function curTab() { const o = openTabs(); if (tab >= o.length) tab = 0; return o[tab]; }


// --- Input: edges and repeats ---
const BUTTONS = [UP, DOWN, LEFT, RIGHT, A, B, X, Y, L, R, START, SELECT];
const held = new Uint16Array(12);
function readPad() { for (const b of BUTTONS) held[b] = btn(b) ? held[b] + 1 : 0; }
const pressed = (b) => held[b] === 1;
/** A press, then repeats while held: after 18 frames every 6, after a second every 2. */
function rep(b) { const h = held[b]; return h === 1 || (h >= 18 && h < 78 && (h - 18) % 6 === 0) || (h >= 78 && h % 2 === 0); }
const handRep = () => held[B] === 1 || (held[B] > 1 && held[B] % 15 === 1);

// --- State ---
let skipTitle = false; // tests set this to land straight in a new run
let state = 'title', paused = false, timer = 0, clock = 0, sub = 0, saveT = 0;
let titleSel = 0, pauseSel = 0, confirm = false;
let EDGE_RGB = [0, 0, 0];
// --- The views (spec 12; art.py): each act's layers, set every frame; the globe and the galaxy on the affine BG2 ---
const LAND = [53, 54, 55, 56], STARC = [65, 66, 67], ARMS = [81, 82, 83, 84], LAMP = 42, BASE = [], BRASSC = [26, 18, 6];
const sceneBg = (n, name, y = 0, wrap = false) => { const c = ART.scenes[name]; bg(n, { mx: c.mx, my: c.my, mw: c.w, mh: c.h, x: 0, y, wrap, show: true }); };
let view = 1, grad = null, spin = 0, galA = 0;
/** Tint CGRAM entries from their art.py colours towards brass, by t (0 to 1). */
function tint(list, t, to = BRASSC) { for (const i of list) { const b = BASE[i]; color(i, ...b.map((v, k) => Math.round(lerp(v, to[k], t)))); } }
function setView() {
  const sv = cine && state === 'cine' ? shot().view : '';
  VY = sv ? 40 : 0;
  view = sv ? ({ world: 2, orrery: 3, black: 0 }[sv] ?? 1) : state === 'title' || !G ? 1 : Math.min(3, G.act);
  for (const i of [LAMP, ...ARMS]) color(i, ...BASE[i]);
  if (fxOn('lampsout')) tint([LAMP], Math.min(1, (cine.t / shot().f) * 1.2 + (shot().view === 'night' ? 0.4 : 0)), [4, 4, 8]);
  if (!view) { bg(0, { show: false }); bg(1, { show: false }); bg(2, { show: false }); grad = null; color(0, 0, 0, 0); return; }
  affine(null); winmask('bg2', null);
  if (view === 1) {
    sceneBg(2, 'town', -VY); sceneBg(1, 'wall', -VY); sceneBg(0, 'bench', -(VIEW_H - 24) - VY);
    if (state === 'title') bg(0, { mh: 9 }); // the bench and, under it, the logo (map rows 15 to 20)
    grad = state === 'title' || sv === 'night' ? ART.gradients.night : ART.gradients.day;
    return;
  }
  bg(0, { show: false }); sceneBg(1, 'stars', -VY, true); bgscroll(1, flr(clock / 8), -VY);
  grad = ART.gradients.space;
  if (view === 2) {
    sceneBg(2, 'globe', 0, true); affine({ a: 1, b: 0, c: 0, d: 0, cx: 0, cy: 0 }); winmask('bg2', { w0: 'out' }); spin = (clock / 3) % 128;
    tint(LAND, Math.min(1, (G.region - 1) * 0.22 + G.wound * 0.34));
  } else {
    sceneBg(2, 'galaxy');
    const gold = fxOn('gold'), out = fxOn('starsout') ? cine.t / shot().f : 0;
    tint(STARC, gold ? 1 : G ? G.starsP : 0); if (gold) tint(ARMS, 0.7); if (out) { tint(STARC, out, [0, 0, 0]); tint(ARMS, out, [0, 0, 0]); }
    galA += fxOn('still') ? 0 : fxOn('spin') ? 0.012 : 1 / 900;
    const k = 0.8, cs = Math.cos(galA) * k, sn = Math.sin(galA) * k;
    affine({ a: cs, b: sn * 2, c: -sn, d: cs * 2, cx: 64, cy: 64 }); bgscroll(2, -64, 64 - 46 - VY);
  }
}
const GLOBE_R = 40, GLOBE_Y = 46;
// the globe's lines, worked out once: each one's half-width on the screen and its row of the map (0 for no globe)
const GLW = [], GROW = [];
for (let y = 0; y < VIEW_H; y++) { const dy = y - GLOBE_Y, w = dy * dy < GLOBE_R * GLOBE_R ? Math.sqrt(GLOBE_R * GLOBE_R - dy * dy) : 0; GLW[y] = w >= 1 ? w : 0; GROW[y] = Math.min(63, Math.max(0, Math.floor((Math.asin(Math.max(-1, Math.min(1, dy / GLOBE_R))) / Math.PI + 0.5) * 64))); }
let bits = []; // cogs dropping in the view: { x, y, vy }

function init() {
  if (dget(VERSION_SLOT) !== SAVE_VERSION) { for (let i = 0; i < 256; i++) dset(i, 0); dset(VERSION_SLOT, SAVE_VERSION); }
  loadFont(); loadBook(); loadSettings(); EDGE_RGB = color(EDGE);
  for (const i of [...LAND, ...STARC, ...ARMS, LAMP]) BASE[i] = color(i);
  if (skipTitle) newRun(1); else toTitle();
}

function toTitle() { state = 'title'; timer = 0; titleSel = 0; confirm = false; paused = false; }
/** A new run: the next cycle (after an ending), with its gift (an Act I invention already made). */
function newRun(seed, gift = 0) {
  G = freshRun(seed, dget(CYCLE_SLOT)); logRows = []; typing = 0; tab = 0; row = 0; top = 0; bits = [];
  state = 'play'; timer = 0; paused = false;
  raise('start');
  if (gift && INV_BY[gift]) { const v = INV_BY[gift]; G.done[gift >> 5] |= 1 << (gift & 31); G.shown[gift >> 5] |= 1 << (gift & 31); G.invs++; applyEffects(v, false); }
  saveRun(); musicT = 0; playScene('opening', () => {});
}
/** The inventions a cycle can give: Act I's, but not the two that end it. */
// Three gifts a cycle, one from each tier (a small help, a middle one, a great one), picked by the cycle number so the
// same three are shown every time; the two inventions that end Act I are never a gift.
const GIFT_TIERS = [[1, 4, 5, 8, 9, 11, 12, 13, 21], [2, 3, 6, 7, 10, 14, 15, 16, 17, 18, 19, 22, 23], [20, 24, 25, 26]];
const TIER = ['A small gift', 'A middle gift', 'A great gift'];
const GIFTS = () => { const c = dget(CYCLE_SLOT); return GIFT_TIERS.map((t, k) => INV_BY[t[(c * [5, 7, 1][k] + k) % t.length]]); };
let giftSel = 0, endSel = 0;
const startCycle = () => { state = 'gift'; giftSel = 0; timer = 0; };
function continueRun() { loadRun(); state = G.act <= 3 ? 'play' : 'choice'; timer = 0; paused = false; bits = []; musicT = 0; }

// --- Update ---
function update() {
  readPad(); clock++;
  if (!paused) play(wantSong());
  if (paused) updatePause();
  else if (state === 'title') updateTitle();
  else if (state === 'play') updatePlay();
  else if (state === 'log') updateLog();
  else if (state === 'miles') updateMiles();
  else if (state === 'cine') updateCine();
  else if (state === 'gift') updateGift();
  else if (state === 'records') { if (timer > 10 && (pressed(A) || pressed(B) || pressed(START))) toTitle(); }
  else if (state === 'choice') updateChoice();
  else if (state === 'ending') updateEnding();
  timer++;
}

function updateTitle() {
  const items = titleItems();
  if (confirm) {
    if (pressed(UP) || pressed(DOWN)) { titleSel ^= 1; fx(SFX.move); }
    if (pressed(B)) { confirm = false; titleSel = 1; fx(SFX.move); }
    else if (pressed(A) || pressed(START)) {
      fx(SFX.select); confirm = false;
      if (titleSel === 1) { if (dget(CYCLE_SLOT)) startCycle(); else newRun(rndi(1, 0x7fffffff)); } else titleSel = 0;
    }
    return;
  }
  if (pressed(UP)) { titleSel = (titleSel + items.length - 1) % items.length; fx(SFX.move); }
  if (pressed(DOWN)) { titleSel = (titleSel + 1) % items.length; fx(SFX.move); }
  if (pressed(A) || pressed(START)) {
    fx(SFX.select);
    const it = items[titleSel];
    if (it === 'CONTINUE') continueRun();
    else if (it === 'MILESTONES') { state = 'records'; timer = 0; }
    else if (hasRun()) { confirm = true; titleSel = 0; }
    else if (dget(CYCLE_SLOT)) startCycle();
    else newRun(rndi(1, 0x7fffffff));
  }
}
const titleItems = () => [...(hasRun() ? ['CONTINUE'] : []), 'NEW STORY', ...(dget(CYCLE_SLOT) ? ['MILESTONES'] : [])];

function updatePlay() {
  if (pressed(START)) { paused = true; pauseSel = 0; saveRun(); fx(SFX.pause); return; }
  if (pressed(SELECT)) { state = 'log'; logScroll = 0; fx(SFX.move); return; }
  const t = curTab(), rows = t.rows();
  if (row >= rows.length) row = rows.length - 1;
  const r = rows[row], o = openTabs().length;
  // The tab strip: UP from the first row puts the cursor on it, where LEFT and RIGHT change tabs (and nothing else);
  // DOWN or A goes back to the rows. A tab change, by any button, leaves the cursor on the strip, so pressing on through
  // the tabs never changes a value by mistake. Only the buttons a phone's touch controls have are needed.
  const tabTo = (d) => { if (o > 1) { tab = (tab + d + o) % o; row = 0; top = 0; onTabs = true; fx(SFX.tab); } };
  if (pressed(L)) tabTo(-1); if (pressed(R)) tabTo(1);
  if (onTabs) {
    if (rep(LEFT)) tabTo(-1); if (rep(RIGHT)) tabTo(1);
    if (pressed(DOWN) || pressed(A)) { onTabs = false; fx(SFX.move); }
  } else {
    if (rep(UP)) { if (row > 0) { row--; fx(SFX.move); } else if (o > 1) { onTabs = true; fx(SFX.move); } }
    if (rep(DOWN) && row < rows.length - 1) { row++; fx(SFX.move); }
    if (r.adj) { if (rep(LEFT)) doRow(() => r.adj(-1)); if (rep(RIGHT)) doRow(() => r.adj(1)); }
    else if (pressed(LEFT) || pressed(RIGHT)) hint('UP to the tabs, then LEFT and RIGHT change them.');
    if (rep(A) && r.a) doRow(r.a);
  }
  if (t.name === 'INVENT') newInv = false;
  if (handRep()) { if (ACT.hand()) { fx([SFX.clink, SFX.wind, SFX.flutter][G.act - 1]); if (G.act === 1) dropCog(); } else hint(why); }
  if (row < top) top = row; if (row >= top + ROWS_SHOWN) top = row - ROWS_SHOWN + 1;
  if (++sub >= TICK_FRAMES) { sub = 0; step(TICK); }
  if (++saveT >= SAVE_EVERY) { saveT = 0; saveRun(); }
  if (typing && clock % 1 === 0) typed += 2;
  for (const c of bits) { c.vy += 0.25; c.y += c.vy; }
  bits = bits.filter((c) => c.y < VIEW_H - 22);
}
function doRow(f) {
  quiet = false;
  if (f()) { if (!quiet) fx(SFX.buy); if (f === ACT.hand) dropCog(); } else { if (!quiet) fx(SFX.no); hint(why); }
}
function hint(s) { hintMsg = s; hintT = 150; }
function dropCog() { if (bits.length < 12) bits.push({ x: 84 + rndi(0, 6), y: 50, vy: -1.5 }); }

function updateMiles() {
  if (rep(UP)) logScroll = Math.max(0, logScroll - 1);
  if (rep(DOWN)) logScroll = Math.min(Math.max(0, MILES.length - 16), logScroll + 1);
  if (pressed(SELECT) || pressed(B) || pressed(START) || pressed(A)) { state = 'play'; fx(SFX.move); }
}
function updateChoice() {
  if (pressed(UP) || pressed(DOWN)) { choiceSel ^= 1; fx(SFX.move); }
  if (timer > 90 && (pressed(A) || pressed(START))) { fx(SFX.select); choose(choiceSel); }
}
/** The ending, then the credits rolling, then NEW CYCLE or TITLE. */
function updateEnding() {
  if (timer < CREDITS_AT) { if (timer > 240 && (pressed(A) || pressed(START))) timer = CREDITS_AT; return; }
  if (pressed(UP) || pressed(DOWN)) { endSel ^= 1; fx(SFX.move); }
  if (timer > CREDITS_AT + 30 && (pressed(A) || pressed(START))) {
    fx(SFX.select);
    if (endSel === 0) startCycle(); else toTitle();
  }
}
function updateGift() {
  const n = GIFTS().length;
  if (rep(UP)) giftSel = (giftSel + n - 1) % n;
  if (rep(DOWN)) giftSel = (giftSel + 1) % n;
  if (pressed(B)) { toTitle(); return; }
  if (timer > 20 && (pressed(A) || pressed(START))) { fx(SFX.select); newRun(rndi(1, 0x7fffffff), GIFTS()[giftSel].id); }
}

function updateLog() {
  const n = logRows.length, page = 17;
  if (rep(UP)) logScroll = Math.min(Math.max(0, n - page), logScroll + 1);
  if (rep(DOWN)) logScroll = Math.max(0, logScroll - 1);
  if (pressed(SELECT) || pressed(B) || pressed(START) || pressed(A)) { state = 'play'; fx(SFX.move); }
}

const PAUSE = () => ['RESUME', 'THE STORY SO FAR', 'MILESTONES', `MUSIC: ${musicOn ? 'ON' : 'OFF'}`, `EFFECTS: ${soundOn ? 'ON' : 'OFF'}`, 'SAVE AND QUIT'];
function updatePause() {
  const n = PAUSE().length;
  if (pressed(UP)) { pauseSel = (pauseSel + n - 1) % n; fx(SFX.move); }
  if (pressed(DOWN)) { pauseSel = (pauseSel + 1) % n; fx(SFX.move); }
  if (pressed(B) || (pressed(START) && pauseSel === 0)) { paused = false; fx(SFX.pause); return; }
  if (!(pressed(A) || pressed(START))) return;
  fx(SFX.select);
  if (pauseSel === 0) paused = false;
  else if (pauseSel === 1) { paused = false; state = 'log'; logScroll = 0; }
  else if (pauseSel === 2) { paused = false; state = 'miles'; logScroll = 0; }
  else if (pauseSel === 3) { musicOn ^= 1; saveSettings(); playing = -2; }
  else if (pauseSel === 4) { soundOn ^= 1; saveSettings(); }
  else { saveRun(); toTitle(); }
}

// --- Draw ---
function draw() {
  cls(); setView();
  if (state === 'title') drawTitle();
  else if (state === 'log') drawFullLog();
  else if (state === 'miles') drawMiles();
  else if (state === 'cine') drawCine();
  else if (state === 'gift') drawGift();
  else if (state === 'records') drawRecords();
  else if (state === 'choice') drawChoice();
  else if (state === 'ending') drawEnding();
  else { drawView(); drawTabs(); drawPanel(); drawLog(); }
  if (paused) drawPause();
}

const S = ART.sprites;
const blinkOf = (c) => (c % 200 < 6 ? S.marco2 : S.marco);
/** Act I: Marco and Paulo, the tinkers on the bench, the workbenches, the cogs. */
function drawShop(c) {
  sprite(blinkOf(c), 60, VIEW_H - 40 + (c % 40 < 20 ? 0 : 1));
  const sv = cine && state === 'cine' ? shot().view : '';
  if (sv ? sv !== 'empty' && !fxOn('empty') : !G || !G.watch) sprite(state === 'title' || fxOn('doze') || (c % 900) > 700 ? S.paulo2 : S.paulo, 82, 34);
  if (!G) return;
  for (let i = 0; i < Math.min(G.tinkers, 14); i++) {
    const x = 116 + i * 9 + Math.round(Math.sin((c + i * 23) / 20) * 3);
    sprite((c + i * 7) % 16 < 8 ? S.tinker0 : S.tinker1, x, VIEW_H - 32);
  }
  for (let i = 0; i < Math.min(G.benches, 6); i++) sprite(S.workbench, 4 + i * 12, 48 - (i % 2) * 2, { prio: 1 });
  for (const b of bits) sprite(S.cog, b.x, b.y);
  const pile = Math.min(6, Math.ceil(G.cogs / 20));
  for (let i = 0; i < pile; i++) sprite(S.cog, 84 + (i % 3) * 6, VIEW_H - 32 - Math.floor(i / 3) * 4);
}
/** Act II: the swarm going round the globe, behind it on the far side. */
function drawWorld(c) {
  const n = Math.min(18, Math.round(swarmLog() * 2));
  for (let i = 0; i < n; i++) {
    const a = c / 140 + (i * 2 * Math.PI) / n, x = 124 + Math.cos(a) * 54, y = GLOBE_Y - 4 + Math.sin(a) * 12 + Math.sin(a * 3 + i) * 3;
    sprite((c + i * 5) % 16 < 8 ? S.tinker0 : S.tinker1, x, y, { prio: Math.sin(a) < 0 ? 0 : 3 });
  }
  circ(128, GLOBE_Y + VY, GLOBE_R + 1, THINK);
}
/** Act III: the orrery's gears over the galaxy, moths at work, and the Rust. */
function drawOrrery(c) {
  sprite(S.sun, 112, GLOBE_Y - 16, { fx: c % 30 < 15 });
  for (let i = 0; i < 3; i++) {
    const a = c / (120 + i * 70) + i * 2, rx = 40 + i * 26, ry = 12 + i * 8;
    sprite(S.planet, 120 + Math.cos(a) * rx, GLOBE_Y - 8 + Math.sin(a) * ry, { fx: c % 20 < 10 });
  }
  const moth = (n, f0, f1, seed) => {
    for (let i = 0; i < n; i++) {
      const a = c / (60 + (i % 5) * 17) + i * seed, x = 128 + Math.cos(a) * (30 + ((i * 37) % 90)), y = GLOBE_Y + Math.sin(a * 1.3 + i) * (18 + ((i * 13) % 26));
      sprite((c + i * 3) % 12 < 6 ? f0 : f1, x, y);
    }
  };
  moth(Math.min(20, Math.round(Math.log10(Math.max(1, G.moths)) * 1.2)), S.moth0, S.moth1, 1.7);
  if (G.rust > 1) moth(Math.min(12, Math.round(Math.log10(G.rust))), S.rust0, S.rust1, 2.9);
}
function drawView() {
  if (view === 1) drawShop(clock); else if (view === 2) drawWorld(clock); else if (view === 3) drawOrrery(clock);
  const m = state === 'play' ? MILES.findIndex((v, j) => G.mile[j] && clock - milestoneAt < 180 && j === lastMile()) : -1;
  if (m >= 0) { const s = `${COG} ${MILES[m].name}`; rectfill(124 - (tw(s) >> 1), 4, tw(s) + 8, 12, PAPER); tx(s, 128 - (tw(s) >> 1), 6, GOLD); }
}

function drawTabs() {
  rectfill(0, TAB_Y, 256, 12, EDGE);
  line(0, TAB_Y + 11, 255, TAB_Y + 11, LINE);
  const o = openTabs(); let x = 6;
  o.forEach((t, i) => {
    const on = i === tab;
    if (on) {
      if (onTabs) rectfill(x - 3, TAB_Y + 1, tw(t.name) + 2 * tw(LM) + 10, 10, ROWC); // the cursor is on the strip
      x = tx(LM, x, TAB_Y + 2, GOLD) + 2; x = tx(t.name, x, TAB_Y + 2, GOLD) + 2; x = tx(RM, x, TAB_Y + 2, GOLD) + 6;
    }
    else {
      x = tx(t.name, x, TAB_Y + 2, DIM) + 1;
      if (t.fresh && t.fresh() && clock % 40 < 28) tx(DOT, x, TAB_Y + 2, GOLD); // something new in it
      x += 6;
    }
  });
}

function drawPanel() {
  rectfill(0, PANEL_Y, 256, LOG_Y - PANEL_Y, PAPER);
  const y0 = PANEL_Y + 3;
  const made = fmt(G.made);
  sys(made, 6, y0, BRASS);
  tx(made === '1' ? 'cog made' : 'cogs made', 6 + made.length * 8 + 4, y0, DIM);
  const coin = G.act === 1 ? money(G.coin) : `${fmts(G.cogs)} ${G.act === 2 ? 'cogs' : ''}`;
  if (G.act === 1) sys(coin, 250 - coin.length * 8, y0, GOOD); else txr(coin, 250, y0, GOOD);
  const t = curTab();
  tx(t.info().join('   '), 6, y0 + 12, INK);
  line(4, y0 + 22, 251, y0 + 22, LINE);
  const rows = t.rows();
  for (let k = 0; k < ROWS_SHOWN; k++) {
    const i = top + k, r = rows[i]; if (!r) break;
    const y = y0 + 26 + k * 10, on = i === row, can = r.ok();
    if (on && !onTabs) { rectfill(3, y - 1, 250, 10, ROWC); tx('>', 6, y, GOLD); }
    tx(r.t, 13, y, can ? INK : DIM);
    txr(r.v(), 250, y, on && !onTabs ? GOLD : can ? BRASS : DIM);
  }
  if (top > 0) tx('^', 244, y0 + 18, DIM);
  if (top + ROWS_SHOWN < rows.length) tx('v', 244, y0 + 26 + ROWS_SHOWN * 10 - 3, DIM);
  const r = rows[row];
  const h = hintT > 0 ? hintMsg : onTabs ? 'LEFT and RIGHT: the tabs.  DOWN: back to the rows.' : r ? r.h() : '';
  if (hintT > 0) hintT--;
  tx(h, 6, LOG_Y - 11, hintT > 0 ? BAD : DIM);
}

function drawLog() {
  rectfill(0, LOG_Y, 256, 224 - LOG_Y, EDGE);
  line(0, LOG_Y, 255, LOG_Y, LINE);
  const n = logRows.length, from = Math.max(0, n - 3);
  let left = typed;
  const firstTyping = n - typing;
  for (let i = from; i < n; i++) {
    let s = logRows[i].s;
    if (typing && i >= firstTyping) {
      // the newest line types itself in: the rows before it in the same story line are counted first
      let before = 0; for (let j = firstTyping; j < i; j++) before += logRows[j].s.length;
      left = typed - before; if (left <= 0) continue;
      if (left < s.length) s = s.slice(0, left);
    }
    tx(s, 5, LOG_Y + 2 + (i - from) * 9, i >= firstTyping && typing ? INK : LOGC); // 9 rows a line: the descenders of the third stay on the screen
  }
  if (typing) { let all = 0; for (let j = firstTyping; j < n; j++) all += logRows[j].s.length; if (typed >= all) typing = 0; }
}

function drawFullLog() {
  rectfill(0, 0, 256, 224, PAPER);
  sysc('THE STORY SO FAR', 6, BRASS);
  line(8, 18, 247, 18, LINE);
  const page = 17, n = logRows.length, end = n - logScroll, from = Math.max(0, end - page);
  for (let i = from; i < end; i++) tx(logRows[i].s, 6, 24 + (i - from) * 10, i === n - 1 ? INK : LOGC);
  tx('UP and DOWN to read back.  B to return.', 6, 214, DIM);
}

function drawMiles() {
  rectfill(0, 0, 256, 224, PAPER);
  sysc('MILESTONES', 6, BRASS);
  line(8, 18, 247, 18, LINE);
  let shown = 0;
  for (let j = logScroll; j < MILES.length && shown < 17; j++, shown++) {
    const y = 24 + shown * 10, t = G.mile[j];
    if (t) { tx(MILES[j].name, 10, y, INK); txr(clockText(t - 1), 246, y, BRASS); }
    else { tx(j === G.mile.indexOf(0) ? '?' : '', 10, y, DIM); if (j === G.mile.indexOf(0)) break; }
  }
  tx(`${G.mile.filter((v) => v).length} of ${MILES.length}   play time ${clockText(G.time)}`, 6, 214, DIM);
}

function drawChoice() {
  rectfill(0, 0, 256, 224, EDGE);
  wrap(STORY[STORY.findIndex((e) => e.ev === 'choice')].text, 220).forEach((l, i) => txc(l, 40 + i * 10, LOGC));
  if (timer > 90) CHOICES.forEach((c, i) => sys(`${i === choiceSel ? '>' : ' '} ${c}`, 80, 140 + i * 14, i === choiceSel ? GOLD : DIM));
}
function drawEnding() {
  rectfill(0, 0, 256, 224, EDGE);
  if (timer >= CREDITS_AT) return drawEndMenu();
  sysc(G.ending === 1 ? 'THE DOMINION ENDING' : 'THE REST ENDING', 40, BRASS);
  const text = STORY[STORY.findIndex((e) => e.ev === (G.ending === 1 ? 'dominion' : 'rest'))].text;
  wrap(text, 220).forEach((l, i) => txc(l, 70 + i * 10, INK));
  tx(`Play time ${clockText(G.time)}`, 6, 200, DIM);
  if (timer > 240) txr('A: the credits', 250, 200, INK);
}

const CREDITS_AT = 900;
const CREDITS = ['CLOCKWORK DOMINION', '', 'Marco, a clockwork automaton', 'Paulo Benedetto, clockmaker of Rotella', 'Lucia',
  'Signore Giuseppe Ferrese, merchant', '', 'Made for the NOVA-16', '', 'Thank you for playing'];
function drawEndMenu() {
  CREDITS.forEach((l, i) => (i ? txc(l, 30 + i * 12, i === 7 ? BRASS : INK) : sysc(l, 30, GOLD)));
  const c = dget(CYCLE_SLOT);
  txc(`The story is told. Cycle ${c + 1} would bring ${RULES[ruleOf(c)]}.`, 160, DIM);
  [`START CYCLE ${c + 1}`, 'TITLE'].forEach((s, i) => sys(`${i === endSel ? '>' : ' '} ${s}`, 72, 178 + i * 12, i === endSel ? GOLD : DIM));
}
function drawGift() {
  rectfill(0, 0, 256, 224, PAPER);
  const c = dget(CYCLE_SLOT), g = GIFTS();
  sysc(`CYCLE ${c + 1}`, 8, BRASS);
  txc(`${RULES[ruleOf(c)]}: ${RULE_HINT[ruleOf(c)]}`, 22, BAD);
  txc(`Every helper and machine works ${c * 10}% harder. Choose a gift:`, 34, INK);
  g.forEach((v, k) => {
    const on = k === giftSel, y = 66 + k * 34;
    if (on) rectfill(3, y - 3, 250, 30, ROWC);
    tx(TIER[k], 14, y, on ? BRASS : DIM);
    tx((on ? '> ' : '  ') + v.name, 10, y + 10, on ? GOLD : INK);
    tx(v.hint, 10, y + 20 - 1, DIM);
  });
  tx('A to begin the cycle with it.  B: the title', 6, 210, DIM);
}
function drawRecords() {
  rectfill(0, 0, 256, 224, PAPER);
  sysc('MILESTONES', 8, BRASS);
  const c = dget(CYCLE_SLOT), e = dget(ENDS_SLOT);
  txc(`${c} ${c === 1 ? 'cycle' : 'cycles'} told.  Endings seen: ${['none', 'Dominion', 'Rest', 'both'][e & 3]}`, 26, INK);
  BESTS.forEach((n, i) => { const t = dget(BEST_SLOT + i); tx(n, 20, 50 + i * 14, t ? INK : DIM); txr(t ? clockText(t - 1) : '-', 236, 50 + i * 14, BRASS); });
  txc('the fastest time to each, over every cycle', 128, DIM);
  txc(`Cogs made in all: ${fmt(getD(ALL_SLOT))}`, 150, GOOD);
  txc('A to return', 200, DIM);
}

function drawTitle() {
  drawShop(clock);
  if (confirm) {
    rectfill(40, 104, 176, 56, PAPER); rect(40, 104, 176, 56, LINE);
    txc('Start a new story?', 112, INK); txc('The one you have will be lost.', 122, DIM);
    ['KEEP MY STORY', 'START AGAIN'].forEach((s, i) => sys(`${i === titleSel ? '>' : ' '} ${s}`, 64, 136 + i * 10, i === titleSel ? GOLD : DIM));
    return;
  }
  txc(dget(CYCLE_SLOT) ? `CYCLE ${dget(CYCLE_SLOT) + 1}` : 'A story in three acts', 144, BRASS);
  titleItems().forEach((s, i) => sys(`${i === titleSel ? '> ' : '  '}${s}`, 84, 160 + i * 13, i === titleSel ? GOLD : DIM));
  txc('A to choose', 212, DIM);
}

function drawPause() {
  const items = PAUSE();
  rectfill(56, 60, 144, 26 + items.length * 12, PAPER); rect(56, 60, 144, 26 + items.length * 12, LINE);
  sysc('PAUSED', 68, BRASS);
  items.forEach((s, i) => tx(`${i === pauseSel ? '>' : ' '} ${s}`, 72, 86 + i * 12, i === pauseSel ? GOLD : INK));
}

/** Each line: the wall's lamplight in the view, the panel's ink below it. */
function scanline(sy) {
  if (irisR) { const d = sy - VY - 60, w = d * d < irisR * irisR ? Math.sqrt(irisR * irisR - d * d) : -1; winpos(1, flr(68 - w), flr(68 + w)); }
  const y = sy - VY;
  if (y < 0) { if (!sy) color(0, 0, 0, 0); return; }
  if (y < VIEW_H) {
    if (grad) gradientLine(grad, y);
    if (view === 2) { // the globe: each line a slice of the sphere, its row of the map squeezed into the circle
      const w = GLW[y];
      if (!w) { if (y === 0 || GLW[y - 1]) bg(2, { show: false }); return; }
      if (!GLW[y - 1]) bg(2, { show: true });
      affine({ a: 32 / w, b: 0, c: 0, d: 0, cx: spin, cy: GROW[y] }); bgscroll(2, spin - 128, 0); winpos(0, 128 - w | 0, 128 + w | 0);
    }
  } else if (y === VIEW_H) { if (VY) { color(0, 0, 0, 0); bg(1, { show: false }); } else color(0, EDGE_RGB[0], EDGE_RGB[1], EDGE_RGB[2]); winpos(0, 1, 0); bg(2, { show: false }); }
}
